CREATE MASKING POLICY IF NOT EXISTS DATAPAI.CFD.MASK_PII_MEDIUM AS (val VARCHAR) RETURNS VARCHAR ->
  CASE WHEN CURRENT_ROLE() = 'PII_ADMIN' OR CURRENT_ROLE() = 'DATA_ENGINEER' THEN val ELSE 'H:' || LEFT(SHA2(val, 256), 16) END;
CREATE MASKING POLICY IF NOT EXISTS DATAPAI.CFD.MASK_PII_LOW AS (val VARCHAR) RETURNS VARCHAR ->
  CASE WHEN CURRENT_ROLE() = 'PII_ADMIN' OR CURRENT_ROLE() = 'DATA_ENGINEER' OR CURRENT_ROLE() = 'ANALYST' THEN val ELSE LEFT(val, 2) || REPEAT('*', GREATEST(LENGTH(val) - 2, 0)) END;
